import 'package:dio/dio.dart';import '../core/api_exceptions.dart';import '../models/author.dart';import '../models/author_query.dart';import '../models/page_result.dart';import 'author_repository.dart';class ApiAuthorRepository implements AuthorRepository{final Dio dio;List<Author>?_cache;ApiAuthorRepository(this.dio);Map<String,dynamic>w(Author a)=>{'firstName':a.firstName,'lastName':a.lastName,'country':a.country,'birthYear':a.birthYear,'bookCount':a.bookCount};@override Future<PageResult<Author>>find(AuthorQuery q)=>retryRead(()=>guard(()async{final r=await dio.get('/authors',queryParameters:{if(q.search.trim().isNotEmpty)'search':q.search.trim(),if(q.country!=null)'country':q.country,'sort':'${q.sortField},${q.sortAscending?'asc':'desc'}','page':q.page,'size':q.size,if(q.includeDeleted)'includeDeleted':true});final d=Map<String,dynamic>.from(r.data as Map);return PageResult(items:(d['items'] as List? ?? []).whereType<Map>().map((e)=>Author.fromJson(Map<String,dynamic>.from(e))).toList(),page:d['page'] as int? ?? 1,size:d['size'] as int? ?? q.size,total:d['total'] as int? ?? 0);}));@override Future<Author?>findById(int id)=>retryRead(()=>guard(()async{final r=await dio.get('/authors/$id');return Author.fromJson(Map<String,dynamic>.from(r.data as Map));}));@override Future<List<Author>>allActive()async{if(_cache!=null)return _cache!;final p=await find(const AuthorQuery(size:50));_cache=p.items;return _cache!;}void clear()=>_cache=null;@override Future<Author>create(Author a)=>guard(()async{final r=await dio.post('/authors',data:w(a));clear();return Author.fromJson(Map<String,dynamic>.from(r.data as Map));});@override Future<Author>update(Author a)=>guard(()async{final r=await dio.put('/authors/${a.id}',data:w(a));clear();return Author.fromJson(Map<String,dynamic>.from(r.data as Map));});@override Future<void>softDelete(int id)=>guard(()async{await dio.delete('/authors/$id');clear();});@override Future<void>hardDelete(int id)=>guard(()async{await dio.delete('/authors/$id',queryParameters:{'hard':true});clear();});@override Future<void>restore(int id)=>guard(()async{await dio.post('/authors/$id/restore');clear();});@override Future<int>deleteMany(List<int>ids)=>guard(()async{final r=await dio.post('/authors/bulk-delete',data:{'ids':ids});clear();return(r.data as Map)['deleted']as int? ?? 0;});}
